import React, { useState, useEffect } from 'react';
import TpoLayout from '../../components/tpo/TpoLayout';
import {
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  Box,
  Chip,
  Avatar,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Divider,
  CircularProgress,
  Alert,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Tooltip,
  Stack,
} from '@mui/material';
import {
  People,
  Work,
  Assessment,
  BarChart,
  TrendingUp,
  EmojiEvents,
  Business,
  School,
  Code,
  Quiz,
  Refresh,
  Visibility,
  Add,
  ArrowForward,
  Star,
  DoneAll,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import {
  BarChart as ReBarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as ReTooltip,
  Legend,
  ResponsiveContainer,
  Cell,
  AreaChart,
  Area,
} from 'recharts';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

interface DashboardStats {
  totalStudents: number;
  totalProblems: number;
  totalTests: number;
  placedStudents: number;
  avgPackage: string;
  activeCompanies: number;
}

interface RecentStudent {
  _id: string;
  userId: {
    profile: {
      firstName: string;
      lastName: string;
    };
    email: string;
  };
  readiness: {
    overallScore: number;
  };
  updatedAt: string;
}

const TpoDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [stats, setStats] = useState<DashboardStats>({
    totalStudents: 0,
    totalProblems: 0,
    totalTests: 0,
    placedStudents: 0,
    avgPackage: '₹0L',
    activeCompanies: 0,
  });
  const [recentStudents, setRecentStudents] = useState<RecentStudent[]>([]);
  const [departmentData, setDepartmentData] = useState<any[]>([]);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      const dashboardRes = await axios.get(`${API_URL}/tpo/dashboard`, { headers });
      
      if (dashboardRes.data.success) {
        const { stats: apiStats, recentStudents: apiStudents } = dashboardRes.data.data;
        setStats({
          totalStudents: apiStats.totalStudents || 0,
          totalProblems: apiStats.totalProblems || 0,
          totalTests: apiStats.totalTests || 0,
          placedStudents: apiStats.placedStudents || 0,
          avgPackage: apiStats.avgPackage || '₹0L',
          activeCompanies: apiStats.activeCompanies || 0,
        });
        setRecentStudents(apiStudents || []);
      }

      const analyticsRes = await axios.get(`${API_URL}/tpo/analytics`, { headers });
      if (analyticsRes.data.success) {
        if (analyticsRes.data.data.deptReadiness) {
          setDepartmentData(analyticsRes.data.data.deptReadiness.map((d: any) => ({
            name: d._id,
            score: Math.round(d.avgReadiness)
          })));
        }
      }
    } catch (err: any) {
      console.error('Error fetching dashboard:', err);
      setError(err.response?.data?.message || 'Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const statCards = [
    { title: 'Total Students', value: stats.totalStudents.toString(), icon: <People />, color: 'primary', path: '/tpo/students' },
    { title: 'DSA Repository', value: stats.totalProblems.toString(), icon: <Code />, color: 'success', path: '/tpo/analytics' },
    { title: 'Testing Hub', value: stats.totalTests.toString(), icon: <Quiz />, color: 'warning', path: '/tpo/analytics' },
    { title: 'Active Partners', value: stats.activeCompanies.toString(), icon: <Business />, color: 'info', path: '/tpo/companies' },
  ];

  const getReadinessColor = (score: number) => {
    if (score >= 80) return '#00f593';
    if (score >= 60) return '#ffd60a';
    return '#f72585';
  };

  if (loading) {
    return (
      <TpoLayout>
        <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
          <CircularProgress color="success" />
        </Box>
      </TpoLayout>
    );
  }

  const pipelineData = [
    { stage: 'Registered', count: stats.totalStudents, fill: '#6c63ff' },
    { stage: 'Profile Complete', count: Math.round(stats.totalStudents * 0.85), fill: '#00d4ff' },
    { stage: 'Test Qualified', count: Math.round(stats.totalStudents * 0.6), fill: '#00f593' },
    { stage: 'Interview Phase', count: Math.round(stats.totalStudents * 0.3), fill: '#ffd60a' },
    { stage: 'Placed', count: stats.placedStudents, fill: '#f72585' },
  ];

  return (
    <TpoLayout>
      <Container maxWidth="xl">
        <Grid container spacing={4}>
          <Grid item xs={12} className="dashboard-entry-1">
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Box>
                <Typography variant="h3" fontWeight="900" sx={{
                  background: 'linear-gradient(135deg, #f0f4ff 0%, #00f593 100%)',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                  letterSpacing: '-1px'
                }}>
                  Placement Engine TPO
                </Typography>
                <Typography variant="subtitle1" color="text.secondary" sx={{ fontSize: '1.1rem' }}>
                  Orchestrating career trajectories and placement excellence
                </Typography>
              </Box>
              <Button
                variant="outlined"
                startIcon={<Refresh />}
                onClick={fetchDashboardData}
                sx={{ borderRadius: 2, borderColor: 'rgba(0, 245, 147, 0.3)', color: '#00f593' }}
              >
                Sync Data
              </Button>
            </Box>
          </Grid>

          {error && (
            <Grid item xs={12}>
              <Alert severity="error" variant="filled" onClose={() => setError(null)} sx={{ borderRadius: 2 }}>
                {error}
              </Alert>
            </Grid>
          )}

          {/* Stats Cards */}
          {statCards.map((stat, index) => (
            <Grid item xs={12} sm={6} md={3} key={index} className={`dashboard-entry-${(index % 3) + 1}`}>
              <Card 
                className="glass-card neon-border-green"
                sx={{ cursor: 'pointer', transition: '0.3s', '&:hover': { transform: 'translateY(-5px)' } }}
                onClick={() => navigate(stat.path)}
              >
                <CardContent>
                  <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Box>
                      <Typography color="text.secondary" variant="caption" fontWeight="bold" sx={{ letterSpacing: '1px', textTransform: 'uppercase' }}>
                        {stat.title}
                      </Typography>
                      <Typography variant="h4" fontWeight="900" mt={0.5} sx={{ color: '#fff' }}>
                        {stat.value}
                      </Typography>
                    </Box>
                    <Avatar
                      sx={{
                        background: `linear-gradient(135deg, ${stat.color === 'primary' ? '#6c63ff' : stat.color === 'success' ? '#00f593' : stat.color === 'warning' ? '#ffd60a' : '#00d4ff'} 0%, rgba(0,0,0,0.5) 100%)`,
                        width: 50,
                        height: 50,
                      }}
                    >
                      {stat.icon}
                    </Avatar>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}

          {/* Placement Pipeline Funnel */}
          <Grid item xs={12} md={7} className="dashboard-entry-2">
            <Card className="glass-card" sx={{ height: 450 }}>
              <CardContent sx={{ height: '100%' }}>
                <Typography variant="h6" fontWeight="bold" mb={3} display="flex" alignItems="center" gap={1}>
                  <TrendingUp color="success" /> Placement Pipeline Efficiency
                </Typography>
                <ResponsiveContainer width="100%" height="80%">
                  <ReBarChart data={pipelineData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" horizontal={false} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="stage" type="category" stroke="#fff" fontSize={12} width={120} />
                    <ReTooltip 
                      cursor={{ fill: 'rgba(255,255,255,0.05)' }}
                      contentStyle={{ backgroundColor: '#0d1228', border: '1px solid rgba(0, 245, 147, 0.3)', borderRadius: 12 }}
                    />
                    <Bar dataKey="count" radius={[0, 10, 10, 0]} barSize={40}>
                      {pipelineData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.fill} />
                      ))}
                    </Bar>
                  </ReBarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>
          </Grid>

          {/* Top Recruiting Partners Spotlight */}
          <Grid item xs={12} md={5} className="dashboard-entry-2">
            <Card className="glass-card" sx={{ height: 450 }}>
              <CardContent>
                <Typography variant="h6" fontWeight="bold" mb={3}>
                  Partner Performance Spotlight
                </Typography>
                <Stack spacing={2}>
                  {[
                    { name: 'TCS', hires: 42, package: '7.5 LPA', growth: '+12%' },
                    { name: 'Google', hires: 5, package: '32.0 LPA', growth: '+25%' },
                    { name: 'Infosys', hires: 38, package: '6.8 LPA', growth: '-5%' },
                    { name: 'Accenture', hires: 25, package: '8.2 LPA', growth: '+8%' },
                    { name: 'Amazon', hires: 3, package: '28.5 LPA', growth: '0%' },
                  ].map((company, idx) => (
                    <Box key={idx} sx={{ 
                      p: 1.8, 
                      borderRadius: '16px',
                      bgcolor: 'rgba(255,255,255,0.02)',
                      border: '1px solid rgba(255,255,255,0.05)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      transition: '0.3s',
                      '&:hover': { bgcolor: 'rgba(255,255,255,0.05)', transform: 'scale(1.02)' }
                    }}>
                      <Box display="flex" alignItems="center" gap={2}>
                        <Avatar sx={{ bgcolor: 'rgba(0, 245, 147, 0.1)', color: '#00f593', fontWeight: 'bold' }}>
                          {company.name.charAt(0)}
                        </Avatar>
                        <Box>
                          <Typography fontWeight="bold" variant="body1">{company.name}</Typography>
                          <Typography variant="caption" color="text.secondary">{company.package}</Typography>
                        </Box>
                      </Box>
                      <Box textAlign="right">
                        <Typography fontWeight="900" color="#00f593">{company.hires} Hires</Typography>
                        <Typography variant="caption" sx={{ color: company.growth.startsWith('+') ? '#00f593' : company.growth.startsWith('-') ? '#f72585' : 'text.secondary' }}>
                          {company.growth} from prev year
                        </Typography>
                      </Box>
                    </Box>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {/* Recent Student Synthesis Table */}
          <Grid item xs={12} md={8} className="dashboard-entry-3">
            <Card className="glass-card">
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
                  <Typography variant="h6" fontWeight="bold" display="flex" alignItems="center" gap={1}>
                    <People color="primary" /> Talent Readiness Stream
                  </Typography>
                  <Button size="small" endIcon={<ArrowForward />} onClick={() => navigate('/tpo/students')}>
                    Synthesis Lab
                  </Button>
                </Box>
                {recentStudents.length === 0 ? (
                  <Typography color="text.secondary" align="center" py={10}>
                    No recent talent activity detected
                  </Typography>
                ) : (
                  <TableContainer component={Box} sx={{ maxHeight: 400 }}>
                    <Table stickyHeader>
                      <TableHead>
                        <TableRow>
                          <TableCell sx={{ bgcolor: 'transparent', color: 'text.secondary', fontWeight: 'bold', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>TALENT</TableCell>
                          <TableCell sx={{ bgcolor: 'transparent', color: 'text.secondary', fontWeight: 'bold', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>READINESS</TableCell>
                          <TableCell align="right" sx={{ bgcolor: 'transparent', color: 'text.secondary', fontWeight: 'bold', borderBottom: '1px solid rgba(255,255,255,0.05)' }}>PROTOCOL</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {recentStudents.slice(0, 5).map((student) => (
                          <TableRow key={student._id} sx={{ '&:hover': { bgcolor: 'rgba(255,255,255,0.02)' } }}>
                            <TableCell sx={{ borderBottom: 'none' }}>
                              <Box display="flex" alignItems="center" gap={2}>
                                <Avatar sx={{ width: 32, height: 32, bgcolor: 'rgba(108, 99, 255, 0.2)', color: '#6c63ff', fontSize: '0.8rem' }}>
                                  {student.userId?.profile?.firstName?.charAt(0)}
                                </Avatar>
                                <Box>
                                  <Typography variant="body2" fontWeight="bold" color="#fff">
                                    {student.userId?.profile?.firstName} {student.userId?.profile?.lastName}
                                  </Typography>
                                  <Typography variant="caption" color="text.secondary">
                                    {student.userId?.email?.split('@')[0]}
                                  </Typography>
                                </Box>
                              </Box>
                            </TableCell>
                            <TableCell sx={{ borderBottom: 'none' }}>
                              <Box display="flex" alignItems="center" gap={1}>
                                <Box sx={{ 
                                  width: 8, height: 8, borderRadius: '50%', 
                                  bgcolor: getReadinessColor(student.readiness?.overallScore || 0),
                                  boxShadow: `0 0 10px ${getReadinessColor(student.readiness?.overallScore || 0)}` 
                                }} />
                                <Typography variant="body2" fontWeight="900" sx={{ color: getReadinessColor(student.readiness?.overallScore || 0) }}>
                                  {student.readiness?.overallScore || 0}%
                                </Typography>
                              </Box>
                            </TableCell>
                            <TableCell align="right" sx={{ borderBottom: 'none' }}>
                              <Tooltip title="Examine Portfolio">
                                <IconButton
                                  size="small"
                                  onClick={() => navigate(`/tpo/students`)}
                                  sx={{ color: '#00f593', bgcolor: 'rgba(0, 245, 147, 0.1)', '&:hover': { bgcolor: 'rgba(0, 245, 147, 0.2)' } }}
                                >
                                  <Visibility fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                )}
              </CardContent>
            </Card>
          </Grid>

          {/* Department Performance Synthesis */}
          <Grid item xs={12} md={4} className="dashboard-entry-3">
            <Card className="glass-card" sx={{ height: '100%' }}>
              <CardContent sx={{ height: '100%' }}>
                <Typography variant="h6" fontWeight="bold" mb={3} display="flex" alignItems="center" gap={1}>
                  <School color="info" /> Academic Nexus
                </Typography>
                <Stack spacing={2.5}>
                  {departmentData.map((dept, idx) => (
                    <Box key={idx}>
                      <Box display="flex" justifyContent="space-between" mb={1} alignItems="flex-end">
                        <Typography variant="body2" fontWeight="bold">{dept.name}</Typography>
                        <Typography variant="caption" sx={{ color: '#00f593', fontWeight: 'bold' }}>{dept.score}% Mastery</Typography>
                      </Box>
                      <Box sx={{ height: 8, bgcolor: 'rgba(255,255,255,0.05)', borderRadius: 4, overflow: 'hidden' }}>
                        <Box sx={{ 
                          height: '100%', 
                          width: `${dept.score}%`, 
                          background: `linear-gradient(90deg, #6c63ff 0%, #00f593 100%)`,
                          borderRadius: 4,
                          boxShadow: '0 0 10px rgba(108, 99, 255, 0.3)'
                        }} />
                      </Box>
                    </Box>
                  ))}
                  {departmentData.length === 0 && (
                    <Typography color="text.secondary" align="center" py={5}>Initializing nexus data...</Typography>
                  )}
                </Stack>
                <Box mt={4} sx={{ p: 2, borderRadius: 3, bgcolor: 'rgba(0, 245, 147, 0.05)', border: '1px dashed rgba(0, 245, 147, 0.2)' }}>
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <DoneAll sx={{ fontSize: 14, color: '#00f593' }} /> CSE is outperforming others by 15% this quarter.
                  </Typography>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          {/* Content Management Quick Gateway */}
          <Grid item xs={12} className="dashboard-entry-3">
            <Card className="glass-card neon-border-cyan">
              <CardContent>
                <Grid container spacing={4} alignItems="center">
                  <Grid item xs={12} md={4}>
                    <Typography variant="h5" fontWeight="900" mb={1}>Knowledge Synthesis</Typography>
                    <Typography variant="body2" color="text.secondary">Expand the practice ecosystem by adding new challenges and assessments.</Typography>
                  </Grid>
                  <Grid item xs={12} md={8}>
                    <Box display="flex" gap={2} flexWrap="wrap">
                      <Button variant="contained" startIcon={<Code />} sx={{ py: 1.5, px: 3, borderRadius: 3, bgcolor: '#6c63ff' }}>Deploy DSA Problem</Button>
                      <Button variant="contained" startIcon={<Quiz />} sx={{ py: 1.5, px: 3, borderRadius: 3, bgcolor: '#00d4ff', color: '#000' }}>Create Aptitude Matrix</Button>
                      <Button variant="outlined" startIcon={<Star />} sx={{ py: 1.5, px: 3, borderRadius: 3, borderColor: '#ffd60a', color: '#ffd60a' }}>Featured Company Prep</Button>
                    </Box>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>
    </TpoLayout>
  );
};

export default TpoDashboard;
