import React, { useState, useEffect, useRef } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Grid,
  Card,
  CardContent,
  TextField,
  Box,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Divider,
  Avatar,
  IconButton,
  CircularProgress,
  Tooltip,
} from '@mui/material';
import { Edit, Close, Save, Cancel, People, School, Work, Business, LocalLibrary, CameraAlt } from '@mui/icons-material';
import { toast } from 'react-toastify';
import axios from 'axios';

interface ProfileData {
  role: string;
  user: {
    id: string;
    email: string;
    profile: {
      firstName: string;
      lastName: string;
      phone?: string;
      department?: string;
      year?: number;
      rollNumber?: string;
      enrollmentNumber?: string;
      course?: string;
      specialization?: string;
    };
  };
  studentInfo?: {
    fathers_name?: string;
    phone?: string;
    date_of_birth?: string;
    academicInfo?: {
      semesterRecords?: any[];
      cgpa?: number;
      backlogs?: any[];
      currentSemester?: number;
      year?: number;
    };
  };
  adminInfo?: {
    collegeName?: string;
    phone?: string;
    email?: string;
    dateOfBirth?: string;
  };
  teacherInfo?: {
    department?: string;
    phone?: string;
    email?: string;
    dateOfBirth?: string;
  };
  tpoInfo?: {
    department?: string;
    phone?: string;
    email?: string;
    dateOfBirth?: string;
  };
}

interface ProfileProps {
  open: boolean;
  onClose: () => void;
}

const Profile: React.FC<ProfileProps> = ({ open, onClose }) => {
  const [profile, setProfile] = useState<ProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [editingAcademic, setEditingAcademic] = useState(false);
  const [collegeName, setCollegeName] = useState('');
  const [tempProfile, setTempProfile] = useState<any>(null);
  const [profilePic, setProfilePic] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleEditProfile = () => {
    setTempProfile({ ...profile });
    if (profile?.adminInfo?.collegeName) {
      setCollegeName(profile.adminInfo.collegeName);
    }
    setEditing(true);
  };

  const handleSaveProfile = async () => {
    try {
      await axios.post('/profile', tempProfile);
      setProfile(tempProfile);
      setEditing(false);
      toast.success('Profile updated successfully');
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to update profile');
    }
  };

  const handleCancelEdit = () => {
    setEditing(false);
    setTempProfile(null);
    if (profile?.adminInfo?.collegeName) {
      setCollegeName(profile.adminInfo.collegeName);
    }
  };

  const handleProfilePicChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      
      // Validate file type
      if (!file.type.startsWith('image/')) {
        toast.error('Please select an image file');
        return;
      }
      
      // Validate file size (2MB max)
      if (file.size > 2 * 1024 * 1024) {
        toast.error('File size exceeds 2MB limit');
        return;
      }
      
      const formData = new FormData();
      formData.append('profilePic', file);
      
      try {
        setUploading(true);
        const response = await axios.post('/profile/upload-picture', formData, {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        });
        
        setProfilePic(response.data.data.profilePic);
        toast.success(response.data.message);
      } catch (error: any) {
        toast.error(error.response?.data?.message || 'Failed to upload profile picture');
      } finally {
        setUploading(false);
        // Reset file input
        if (fileInputRef.current) {
          fileInputRef.current.value = '';
        }
      }
    }
  };

  const getRoleDisplay = (): string => {
    if (profile?.role) {
      const role = profile.role;
      return role.charAt(0).toUpperCase() + role.slice(1);
    }
    return 'User';
  };

  useEffect(() => {
    if (open) {
      fetchProfile();
    }
  }, [open]);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      const response = await axios.get('/profile');
      setProfile(response.data.data);
      
      // Set profile picture based on role
      if (response.data.data.studentInfo?.profilePic) {
        setProfilePic(response.data.data.studentInfo.profilePic);
      } else if (response.data.data.employeeInfo?.profilePic) {
        setProfilePic(response.data.data.employeeInfo.profilePic);
      } else if (response.data.data.adminInfo?.profilePic) {
        setProfilePic(response.data.data.adminInfo.profilePic);
      }
      
      if (response.data.data.adminInfo) {
        setCollegeName(response.data.data.adminInfo.collegeName);
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || 'Failed to fetch profile');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
        <DialogTitle>Loading Profile...</DialogTitle>
      </Dialog>
    );
  }

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h6">User Profile</Typography>
          <Button onClick={onClose} startIcon={<Close />}>Close</Button>
        </Box>
      </DialogTitle>
      
      <DialogContent dividers>
        <Grid container spacing={3}>
          {/* Profile Picture Section */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Box display="flex" justifyContent="center" alignItems="center" flexDirection="column">
                  <Box position="relative" display="inline-flex" justifyContent="center">
                    <Avatar 
                      src={profilePic ? `${process.env.REACT_APP_API_URL || window.location.origin}${profilePic}` : undefined}
                      sx={{ 
                        width: 120, 
                        height: 120, 
                        fontSize: 40,
                        bgcolor: 'secondary.main'
                      }}
                    >
                      {!profilePic && profile?.user?.profile.firstName?.charAt(0)}
                    </Avatar>
                    <Tooltip title="Change Profile Picture">
                      <IconButton
                        onClick={() => fileInputRef.current?.click()}
                        size="small"
                        sx={{
                          position: 'absolute',
                          bottom: 0,
                          right: 0,
                          backgroundColor: 'white',
                          borderRadius: '50%',
                          border: '2px solid white',
                          '&:hover': {
                            backgroundColor: 'grey.200',
                          },
                        }}
                      >
                        {uploading ? <CircularProgress size={20} /> : <CameraAlt fontSize="small" />}
                      </IconButton>
                    </Tooltip>
                  </Box>
                  <Typography variant="h6" mt={2} textAlign="center">
                    {profile?.user?.profile.firstName} {profile?.user?.profile.lastName}
                  </Typography>
                  <Typography variant="body2" color="textSecondary" textAlign="center">
                    {getRoleDisplay()}
                  </Typography>
                </Box>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleProfilePicChange}
                  style={{ display: 'none' }}
                  accept="image/*"
                />
              </CardContent>
            </Card>
          </Grid>
          
          {/* Basic User Info */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Basic Information
                </Typography>
                
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Email"
                      value={profile?.user?.email || ''}
                      disabled={!editing}
                      onChange={(e) => setTempProfile({...tempProfile, user: {...tempProfile?.user, email: e.target.value}})}
                    />
                  </Grid>
                  
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="First Name"
                      value={editing ? tempProfile?.user?.profile.firstName || '' : profile?.user?.profile.firstName || ''}
                      disabled={!editing}
                      onChange={(e) => setTempProfile({...tempProfile, user: {...tempProfile?.user, profile: {...tempProfile?.user?.profile, firstName: e.target.value}}})}
                    />
                  </Grid>
                  
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Last Name"
                      value={editing ? tempProfile?.user?.profile.lastName || '' : profile?.user?.profile.lastName || ''}
                      disabled={!editing}
                      onChange={(e) => setTempProfile({...tempProfile, user: {...tempProfile?.user, profile: {...tempProfile?.user?.profile, lastName: e.target.value}}})}
                    />
                  </Grid>
                  
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Phone"
                      value={editing ? tempProfile?.user?.profile.phone || '' : profile?.user?.profile.phone || ''}
                      disabled={!editing}
                      onChange={(e) => setTempProfile({...tempProfile, user: {...tempProfile?.user, profile: {...tempProfile?.user?.profile, phone: e.target.value}}})}
                    />
                  </Grid>
                  
                  <Grid item xs={12} sm={6}>
                    <FormControl fullWidth disabled={!editing}>
                      <InputLabel>Department</InputLabel>
                      <Select
                        value={editing ? tempProfile?.user?.profile.department || '' : profile?.user?.profile.department || ''}
                        label="Department"
                        onChange={(e) => setTempProfile({...tempProfile, user: {...tempProfile?.user, profile: {...tempProfile?.user?.profile, department: e.target.value}}})}
                      >
                        <MenuItem value="">None</MenuItem>
                        <MenuItem value="Computer Science">Computer Science</MenuItem>
                        <MenuItem value="Electrical">Electrical</MenuItem>
                        <MenuItem value="Mechanical">Mechanical</MenuItem>
                        <MenuItem value="Civil">Civil</MenuItem>
                        <MenuItem value="Chemical">Chemical</MenuItem>
                        <MenuItem value="Other">Other</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  
                  {profile?.role === 'admin' && (
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        label="College Name"
                        value={editing ? collegeName : profile?.adminInfo?.collegeName || ''}
                        disabled={!editing}
                        onChange={(e) => setCollegeName(e.target.value)}
                      />
                    </Grid>
                  )}
                </Grid>
              </CardContent>
            </Card>
          </Grid>
          
          {/* Role-Specific Info */}
          {(profile?.role === 'student' || profile?.role === 'teacher' || profile?.role === 'tpo') && (
            <Grid item xs={12}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    {profile.role === 'student' ? 'Student' : profile.role === 'teacher' ? 'Teacher' : 'TPO'} Information
                  </Typography>
                  
                  <Grid container spacing={2}>
                    {profile?.role === 'student' && profile?.studentInfo && (
                      <>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Father's Name"
                            value={profile.studentInfo.fathers_name || ''}
                            disabled
                          />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Date of Birth"
                            value={profile.studentInfo.date_of_birth || ''}
                            disabled
                          />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Phone"
                            value={profile.studentInfo.phone || ''}
                            disabled
                          />
                        </Grid>
                      </>
                    )}
                    
                    {(profile?.role === 'teacher' || profile?.role === 'tpo') && (
                      <>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Phone"
                            value={profile.role === 'teacher' ? profile.teacherInfo?.phone || '' : profile.tpoInfo?.phone || ''}
                            disabled
                          />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Email"
                            value={profile.role === 'teacher' ? profile.teacherInfo?.email || '' : profile.tpoInfo?.email || ''}
                            disabled
                          />
                        </Grid>
                      </>
                    )}
                  </Grid>
                </CardContent>
              </Card>
            </Grid>
          )}
          
          {/* Academic Records for Students */}
          {profile?.role === 'student' && profile.studentInfo && (
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>Academic Records</Typography>
              
              <Card>
                <CardContent>
                  <Grid container spacing={2}>
                    {Array.from({ length: 8 }, (_, i) => i + 1).map(semester => {
                      const record = profile.studentInfo?.academicInfo?.semesterRecords?.find(r => r.semester === semester);
                      return (
                        <Grid item xs={6} sm={3} key={semester}>
                          <Typography variant="body2" color="textSecondary">Semester {semester}</Typography>
                          <Typography variant="h6" color={record?.sgpa ? "primary" : "textSecondary"}>
                            {record?.sgpa ? record.sgpa.toFixed(2) : 'N/A'}
                          </Typography>
                        </Grid>
                      );
                    })}
                  </Grid>
                  <Divider sx={{ my: 2 }} />
                  <Grid container spacing={2}>
                    <Grid item xs={6} sm={3}>
                      <Typography variant="body2" color="textSecondary">Current CGPA</Typography>
                      <Typography variant="h6" color="primary">
                        {profile.studentInfo?.academicInfo?.cgpa ? profile.studentInfo.academicInfo.cgpa.toFixed(2) : 'N/A'}
                      </Typography>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Typography variant="body2" color="textSecondary">Current Semester</Typography>
                      <Typography variant="h6" color="primary">
                        {profile.studentInfo?.academicInfo?.currentSemester || 'N/A'}
                      </Typography>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </Grid>
          )}
        </Grid>
      </DialogContent>
      
      <DialogActions>
        {!editing && (
          <Button onClick={handleEditProfile} variant="outlined" startIcon={<Edit />}>Edit Profile</Button>
        )}
        {editing && (
          <>
            <Button onClick={handleCancelEdit} color="secondary">Cancel</Button>
            <Button onClick={handleSaveProfile} variant="contained" color="primary">Save</Button>
          </>
        )}
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  );
};

export default Profile;