import React, { useState, useEffect } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { Box, CircularProgress } from '@mui/material';
import StudentLayout from '../../components/student/StudentLayout';
import DashboardHome from './DashboardHome';
import ResumeAnalysis from './ResumeAnalysis';
import DSAPractice from './DSAPractice';
import ProblemDetail from './ProblemDetail';
import AptitudePractice from './AptitudePractice';
import AptitudeTest from './AptitudeTest';
import MockInterviews from './MockInterviews';
import EnglishAnalysis from './EnglishAnalysis';
import ReadinessAnalyzer from './ReadinessAnalyzer';
import ReadinessTest from './ReadinessTest';
import CoreSubjects from './CoreSubjects';
import Analytics from './Analytics';

const ReadinessCheck: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [loading, setLoading] = useState(true);
  const [needsTest, setNeedsTest] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const checkReadiness = async () => {
      try {
        const response = await axios.get('/student/dashboard');
        const readiness = response.data.data?.readiness;
        if (!readiness || !readiness.lastAnalyzed) {
          setNeedsTest(true);
        }
      } catch (error) {
        console.error('Failed to check readiness:', error);
      } finally {
        setLoading(false);
      }
    };
    checkReadiness();
  }, []);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  if (needsTest && location.pathname !== '/student/readiness/test') {
    return <Navigate to="/student/readiness/test" replace />;
  }

  return <>{children}</>;
};

const StudentDashboard: React.FC = () => {
  return (
    <StudentLayout>
      <ReadinessCheck>
        <Routes>
          <Route path="/" element={<DashboardHome />} />
          <Route path="/resume" element={<ResumeAnalysis />} />
          <Route path="/dsa" element={<DSAPractice />} />
          <Route path="/dsa/problem/:id" element={<ProblemDetail />} />
          <Route path="/aptitude" element={<AptitudePractice />} />
          <Route path="/aptitude/test/:id" element={<AptitudeTest />} />
          <Route path="/interviews" element={<MockInterviews />} />
          <Route path="/english" element={<EnglishAnalysis />} />
          <Route path="/readiness" element={<ReadinessAnalyzer />} />
          <Route path="/readiness/test" element={<ReadinessTest />} />
          <Route path="/core-subjects" element={<CoreSubjects />} />
          <Route path="/analytics" element={<Analytics />} />
          <Route path="*" element={<Navigate to="/student" replace />} />
        </Routes>
      </ReadinessCheck>
    </StudentLayout>
  );
};

export default StudentDashboard;
